module mod_mult #(
    parameter n = 8,
    parameter delta = 3,
    parameter modulus = 259
)(
    input [n-1:0] a,
    input [n-1:0] b,
    input delta_a,
    input delta_b,
    output reg [n-1:0] p,
    output reg delta_p
);

    wire [2:0] AH = a[n-1:5];
    wire [2:0] AM = a[4:2];
    wire [1:0] AL = a[1:0];
    wire [2:0] BH = b[n-1:5];
    wire [2:0] BM = b[4:2];
    wire [1:0] BL = b[1:0];

    wire [n:0] pp_ll;
    wire [n:0] pp_lm;
    wire [n:0] pp_lh;
    wire [n:0] pp_ml;
    wire [n:0] pp_mm;
    wire [n:0] pp_mh;
    wire [n:0] pp_hl;
    wire [n:0] pp_hm;
    wire [n:0] pp_hh;

    logic_mod259_plus_LL logic_ll (
        .address({AL, delta_a, BL, delta_b}),
        .data(pp_ll)
    );

    logic_mod259_plus_LM logic_lm (
        .address({AL, delta_a, BM}),
        .data(pp_lm)
    );

    logic_mod259_plus_LH logic_lh (
        .address({AL, delta_a, BH}),
        .data(pp_lh)
    );

    logic_mod259_plus_ML logic_ml (
        .address({AM, BL, delta_b}),
        .data(pp_ml)
    );

    logic_mod259_plus_MM logic_mm (
        .address({AM, BM}),
        .data(pp_mm)
    );

    logic_mod259_plus_MH logic_mh (
        .address({AM, BH}),
        .data(pp_mh)
    );

    logic_mod259_plus_HL logic_hl (
        .address({AH, BL, delta_b}),
        .data(pp_hl)
    );

    logic_mod259_plus_HM logic_hm (
        .address({AH, BM}),
        .data(pp_hm)
    );

    logic_mod259_plus_HH logic_hh (
        .address({AH, BH}),
        .data(pp_hh)
    );

    wire [n:0] sum1, sum2, sum3;
    wire [n+1:1] carry1, carry2, carry3;

    compressor3_2 comp0 (
        .x1(pp_ll[0]),
        .x2(pp_lm[0]),
        .x3(pp_lh[0]),
        .sum(sum1[0]),
        .cout(carry1[1])
    );

    compressor3_2 comp1 (
        .x1(pp_ml[0]),
        .x2(pp_mm[0]),
        .x3(pp_mh[0]),
        .sum(sum2[0]),
        .cout(carry2[1])
    );

    compressor3_2 comp2 (
        .x1(pp_hl[0]),
        .x2(pp_hm[0]),
        .x3(pp_hh[0]),
        .sum(sum3[0]),
        .cout(carry3[1])
    );

    genvar i;
    generate
        for (i = 1; i < 9; i = i + 1) begin : compressor_stage1
            compressor3_2 comp3 (
                .x1(pp_ll[i]),
                .x2(pp_lm[i]),
                .x3(pp_lh[i]),
                .sum(sum1[i]),
                .cout(carry1[i+1])
            );

            compressor3_2 comp4 (
                .x1(pp_ml[i]),
                .x2(pp_mm[i]),
                .x3(pp_mh[i]),
                .sum(sum2[i]),
                .cout(carry2[i+1])
            );

            compressor3_2 comp5 (
                .x1(pp_hl[i]),
                .x2(pp_hm[i]),
                .x3(pp_hh[i]),
                .sum(sum3[i]),
                .cout(carry3[i+1])
            );
        end
    endgenerate

    wire [n+1:0] sum4;
    wire [n+1:1] sum5;
	assign sum5[n+1] = 1'b0;
    wire [n+2:1] carry4;
    wire [n+1:1] carry5;
	assign carry5[1] = 1'b0;

    compressor3_2 comp6 (
        .x1(sum1[0]),
        .x2(sum2[0]),
        .x3(sum3[0]),
        .sum(sum4[0]),
        .cout(carry4[1])
    );

    genvar j;
    generate
        for (j = 1; j < 9; j = j + 1) begin : compressor_stage2
            compressor3_2 comp7 (
                .x1(sum1[j]),
                .x2(sum2[j]),
                .x3(sum3[j]),
                .sum(sum4[j]),
                .cout(carry4[j+1])
            );

            compressor3_2 comp8 (
                .x1(carry1[j]),
                .x2(carry2[j]),
                .x3(carry3[j]),
                .sum(sum5[j]),
                .cout(carry5[j+1])
            );
        end
    endgenerate

    compressor3_2 comp9 (
        .x1(carry1[n+1]),
        .x2(carry2[n+1]),
        .x3(carry3[n+1]),
        .sum(sum4[n+1]),
        .cout(carry4[n+2])
    );

    wire [n+2:1] sum6;
    wire [n+2:2] carry6;
    wire [n+1:0] cout_vec;
	assign cout_vec[0] = 1'b0;

    genvar k;
    generate
        for (k = 1; k < 10; k = k + 1) begin : compressor_stage3
            compressor4_2 comp10 (
                .x1(sum4[k]),
                .x2(sum5[k]),
                .x3(carry4[k]),
                .x4(carry5[k]),
                .cin(cout_vec[k-1]),
                .sum(sum6[k]),
                .carry(carry6[k+1]),
                .cout(cout_vec[k])
            );
        end
    endgenerate

    assign sum6[n+2] = cout_vec[n+1];

    wire [n:0] logic_data1;

    logic_rom_mult_plus_1_259 logic_rom_1 (
        .address({sum6[n+2], carry6[n+2], carry4[n+2], carry6[n+1], sum6[n+1], carry6[n]}),
        .data(logic_data1)
    );

    wire [n:0] csa_sum;
    wire [n+1:1] csa_carry;

    csa #(
        .n(n+2)
    ) csa_0 (
        .a(logic_data1),
        .b({sum6[n:1], sum4[0]}),
        .c({carry6[n:2], 2'b0}),
        .sum_out(csa_sum),
        .carry_out(csa_carry)
    );

    wire [n:0] logic_data2;

    logic_rom_mult_plus_2_259 logic_rom_2 (
        .address({csa_carry[n+1], csa_sum[n], csa_carry[n], csa_sum[n-1], csa_carry[n-1]}),
        .data(logic_data2)
    );

    wire [n-2:0] csa_sum2;
    wire [n-1:1] csa_carry2;

    csa #(
        .n(n)
    ) csa_1 (
        .a(logic_data2[n-2:0]),
        .b({csa_sum[n-2:0]}),
        .c({csa_carry[n-2:1], 1'b0}),
        .sum_out(csa_sum2),
        .carry_out(csa_carry2)
    );

    wire [n:0] y;
    wire delta_aux;
    assign y = {logic_data2[n-1], csa_sum2} + {csa_carry2, 1'b0};

    assign delta_aux = logic_data2[n] ^ y[n];

    always @(*) begin
        p = y[n-1:0];
        delta_p = delta_aux;
    end
endmodule
